{"description":"Buoy status indicator (small integer, higher is stronger).","name":"buoy_signal","type":"int"}
{"description":"Messages confirmed at shore.","name":"delivered","type":"int"}
{"description":"Priority messages confirmed at shore by their deadline.","name":"priority_delivered","type":"int"}
{"description":"Messages that never reached shore.","name":"lost","type":"int"}
